import {test} from 'node:test';
import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';
import {JSDOM} from 'jsdom';
import {SnapshotSync} from '../src/snapshot-sync.js';
import {mergeSnapshots} from '../src/snapshot-merge.js';
const html=readFileSync('index.html','utf8');
async function boot(user,stored=null,connected=false,options={}){
 const dom=new JSDOM(html,{url:'https://samuelcnovaes.github.io/ciclo-de-estudos/',runScripts:'outside-only',pretendToBeVisual:true});const w=dom.window;w.eval(readFileSync('src/performance-priorities.js','utf8'));w.eval(readFileSync('src/tec-session.js','utf8'));w.eval(readFileSync('src/tec-planner-bridge.js','utf8'));w.structuredClone=structuredClone;w.testIntervals=[];w.setInterval=(callback,delay)=>{w.testIntervals.push({callback,delay});return 0};w.setTimeout=(callback,delay)=>{if(delay===1500)callback();return 0};w.confirm=()=>true;
 w.HTMLDialogElement.prototype.showModal=function(){this.open=true};w.HTMLDialogElement.prototype.close=function(){this.open=false};
 if(options.Worker)w.Worker=options.Worker;
 if(stored)w.localStorage.setItem('ciclo-estudos-v1:cloud:'+user.id,stored);
 w.CicloCloud={prepare:async()=>({user,key:user?'ciclo-estudos-v1:cloud:'+user.id:undefined,mode:user?'cloud':'local'}),attach:()=>{}};
 if(connected){w.eval(readFileSync('cloud-ui.js','utf8'));const writes=[],cloud={user,key:'ciclo-estudos-v1:cloud:'+user.id,account:{id:user.id,standalone:true},mode:'cloud',client:{auth:{}}};cloud.sync=new SnapshotSync({load:async()=>null,write:async(payload,version)=>{writes.push(structuredClone(payload));return {version:(version||0)+1}},cache:()=>{},validate:()=>{},onStatus:(status,error)=>{cloud.status=status;cloud.error=error;cloud.renderStatus?.()}});cloud.sync.version=1;w.CicloCloud.prepare=async()=>cloud;w.testCloud={cloud,writes};}

 const scripts=w.document.querySelectorAll('script:not([src]):not([type="application/json"])');for(const s of scripts)w.eval(s.textContent.replace('function plannerRange(){',"window.plannerTest={showReminder:(...args)=>showStudyReminder(...args),setSession:s=>{state.session=s},openRecord:()=>openRecord(),timerRefresh:()=>updateTimer(),questionPace:(...args)=>questionGoalPace(...args),questionGoals:(...args)=>questionGoalSettings(...args),bridgeLoad:async client=>{cloud.client=client;await refreshPerformancePlans();return performanceBridge.allowed},reportPriorities:(allowed,payload)=>{performanceBridge.allowed=allowed;performanceBridge.priorityReport=payload;performanceBridge.priorityExamId=payload?.insights?.integrationExamId||'';performanceBridge.priorityBank=payload?.insights?.mainBank||'Geral';},performance:(allowed,plans)=>{performanceBridge.allowed=allowed;performanceBridge.plans=plans},editRecord:id=>editHistory(id),missingVerb:(...args)=>missingVerb(...args),reminderDue:(...args)=>studyReminderDue(...args),suggestions:(...args)=>accumulatedReviewSuggestions(...args),autoTasks:(...args)=>automaticTaskAmounts(...args),autoTimes:(...args)=>automaticPlanningTimes(...args),schedule:(...args)=>curriculumSchedule(...args),stageReady:s=>curriculumReady(s),exams:()=>ensureExams(),selectExam,createExam:createExamWorkspace,examCatalog,aggregate:()=>aggregateExamState(),set:next=>{state.subjects=next.subjects;state.stages=next.stages;},newPlan:(...args)=>createPlanning(...args),switchPlan:switchPlanning,plans:()=>planningStore(),save:()=>persist(),validate:(...args)=>validateBackup(...args),edital:()=>editalState(),buildPlan:(...args)=>buildEditalPlan(...args),applyPlan:applyEditalPlan,record:()=>openRecord(),task:(...args)=>openTaskProgress(...args),topics:subjectTopicNames,order:(...args)=>reorderCalendarStage(...args),project:end=>projectCycle(end),configure:patch=>{Object.assign(state,patch);},assign:(...args)=>assignAutomaticCycle(...args),apply:(...args)=>applyRecord(...args),move:moveReview,reviews:()=>state.reviews,round:()=>state.roundId,ready:id=>calendarStageReady(id),overview:weeklyCycleOverview,button:block=>planStartButton(block)};function plannerRange(){").replace('function backupReminderDue(){','window.testBackupDue=backupReminderDue;window.testCheckBackup=checkBackupReminder;function backupReminderDue(){'));
 await new Promise(r=>setTimeout(r,25));return dom;
}
test('requires cloud login and does not initialize personal data before login',async()=>{const d=await boot(null);assert.equal(d.window.document.body.classList.contains('login-required'),true);assert.equal(d.window.document.getElementById('cloudDialog').open,true);assert.equal(d.window.localStorage.length,0);d.window.close();});
test('new authenticated account gets empty studies',async()=>{const d=await boot({id:'new-user',email:'user@example.invalid'});assert.ok(d.window.document.getElementById('content').textContent.includes('Prepare seu planejamento'));const data=JSON.parse(d.window.localStorage.getItem('ciclo-estudos-v1:cloud:new-user'));assert.equal(data.subjects.length,0);assert.equal(data.stages.length,0);assert.equal(data.history.length,0);d.window.close();});
test('assets are relative and performance opens a separate tab',()=>{const d=new JSDOM(html);for(const el of d.window.document.querySelectorAll('script[src]'))assert.ok(el.getAttribute('src').startsWith('./'));assert.equal(d.window.document.querySelector('.performance-link').target,'_blank');assert.ok(!html.includes('PHOTO_PROGRESS'));assert.ok(!html.includes('ACCOUNT_CONTEXT_JSON'));d.window.close();});

test('new account checklist guides subjects, goals, then cycle',async()=>{const d=await boot({id:'empty'}),w=d.window;assert.equal(w.document.getElementById('setupGoals').disabled,true);w.document.getElementById('setupSubjects').click();w.document.getElementById('batchSubjectNames').value='Direito Tributário';w.document.getElementById('batchSubjectForm').dispatchEvent(new w.Event('submit',{cancelable:true}));assert.equal(w.document.getElementById('setupGoals').disabled,false);assert.equal(w.document.getElementById('setupCycle').disabled,true);w.document.getElementById('setupGoals').click();assert.equal(w.document.getElementById('goalsDialog').open,true);w.close();});

test('cloud account never prompts for periodic backup',async()=>{const d=await boot({id:'cloud'}),w=d.window;w.testCheckBackup();assert.equal(w.testBackupDue(),false);assert.equal(w.document.getElementById('backupReminder').open,false);w.close();});

test('weekly calendar lets students choose any stage without completing previous stages',async()=>{const d=await boot({id:'planner'}),w=d.window;const subjects=[{id:'a',name:'Direito',color:'#315fb3'},{id:'b',name:'Auditoria',color:'#315fb3'}];const stages=[{id:'1',subjectId:'a',target:3600,done:0,content:'Teoria'},{id:'2',subjectId:'b',target:3600,done:0,content:'Questões'}];w.plannerTest.set({subjects,stages});assert.match(w.plannerTest.overview(),/Direito/);assert.match(w.plannerTest.overview(),/Auditoria/);assert.equal(w.plannerTest.ready('1'),true);assert.equal(w.plannerTest.ready('2'),true);assert.doesNotMatch(w.plannerTest.button({stageId:'2',round:0}),/disabled/);assert.match(w.plannerTest.button({stageId:'2',round:0}),/data-calendar-choice/);stages[0].done=3600;assert.equal(w.plannerTest.ready('2'),true);assert.equal(w.plannerTest.ready('1'),true);w.close();});

test('inserts a manual review without generating study history',async()=>{const d=await boot({id:'reviews'}),w=d.window;w.plannerTest.set({subjects:[{id:'a',name:'Auditoria',color:'#315fb3',contents:[]}],stages:[]});w.document.querySelector('[data-tab="reviews"]').click();w.document.getElementById('insertReview').click();w.document.getElementById('manualReviewContent').value='Documentação de auditoria';w.document.getElementById('manualReviewDate').value='2030-01-15';w.document.getElementById('manualReviewForm').dispatchEvent(new w.Event('submit',{cancelable:true}));const data=JSON.parse(w.localStorage.getItem('ciclo-estudos-v1:cloud:reviews'));assert.equal(data.history.length,0);assert.equal(data.reviews.length,1);assert.equal(data.reviews[0].dueDate,'2030-01-15');assert.match(w.document.getElementById('content').textContent,/Documentação de auditoria/);w.close();});

test('quick study counts matching review stage and edits move the credit without duplicating',async()=>{const d=await boot({id:'auto'}),w=d.window;const stages=[{id:'theory',subjectId:'a',content:'Conteúdo novo',target:3600,done:0},{id:'review',subjectId:'a',content:'Resumo (Revisão)',target:3600,done:0}];w.plannerTest.set({subjects:[{id:'a',name:'Auditoria',color:'#315fb3'}],stages});const first={stageId:'inline',subjectId:'a',content:'Revisão',seconds:600,roundId:w.plannerTest.round()};w.plannerTest.assign(first);w.plannerTest.apply(first);assert.equal(stages[1].done,600);const edited={...first,content:'Conteúdo novo',seconds:900};w.plannerTest.assign(edited,first);w.plannerTest.apply(edited,first);assert.equal(stages[1].done,0);assert.equal(stages[0].done,900);const review={id:'r',status:'scheduled',dueDate:'2030-01-15',manualSource:{subjectId:'a',name:'Auditoria'}};w.plannerTest.reviews().push(review);assert.equal(w.plannerTest.move('r','2000-01-01'),false);assert.equal(review.dueDate,'2030-01-15');w.close();});

test('reviews all filter includes every status and cycle calendar offers only weeks',async()=>{const d=await boot({id:'filters'}),w=d.window;w.plannerTest.set({subjects:[{id:'a',name:'Auditoria',color:'#315fb3'}],stages:[]});for(const [i,status] of ['scheduled','completed','ignored'].entries())w.plannerTest.reviews().push({id:'r'+i,status,dueDate:'2030-01-01',offsetDays:0,manualSource:{subjectId:'a',name:'Auditoria',content:'Conteúdo '+i,date:new Date().toISOString()}});w.document.querySelector('[data-tab="reviews"]').click();w.document.querySelector('[data-review-tab="all"]').click();for(let i=0;i<3;i++)assert.match(w.document.getElementById('content').textContent,new RegExp('Conteúdo '+i));w.document.querySelector('[data-tab="planner"]').click();assert.equal(w.document.querySelectorAll('[data-plan-view]').length,3);assert.equal(w.document.querySelectorAll('[data-plan-day]').length,0);assert.match(w.document.getElementById('content').textContent,/Calendário do ciclo/);assert.ok(w.document.getElementById('scheduleReviews').closest('.schedule-review-highlight'));w.close();});

test('daily projection includes full last stage and month stops at weekly goal',async()=>{const d=await boot({id:'projection'}),w=d.window;const date=new Date();date.setHours(12,0,0,0);date.setDate(date.getDate()+((8-date.getDay())%7||7));const key=x=>x.toISOString().slice(0,10),end=new Date(date);end.setDate(end.getDate()+6);const subjects=['a','b','c'].map(id=>({id,name:id,color:'#315fb3'})),stages=subjects.map((m,i)=>({id:'s'+i,subjectId:m.id,content:'Teoria',target:4500,done:0}));w.plannerTest.configure({subjects,stages,goals:{daily:10800,weekly:21600,dailyTasks:0,weeklyTasks:0},planner:{startDate:key(date),anchor:key(date),startTime:'08:00',weekdays:[0,1,2,3,4,5,6],view:'week'}});let plan=w.plannerTest.project(end);assert.equal(plan[key(date)].length,3);assert.equal(plan[key(date)].reduce((n,b)=>n+b.seconds,0),13500);w.plannerTest.configure({planner:{startDate:key(date),anchor:key(date),startTime:'08:00',weekdays:[0,1,2,3,4,5,6],view:'month'}});plan=w.plannerTest.project(end);assert.equal(Object.values(plan).flat().reduce((n,b)=>n+b.seconds,0),22500);w.close();});

test('calendar reordering persists shared cycle order while preserving progress',async()=>{const d=await boot({id:'order'}),w=d.window;const stages=['a','b','c'].map((id,i)=>({id,subjectId:'s',content:'Teoria '+i,target:3600,done:i*100}));w.plannerTest.set({subjects:[{id:'s',name:'Auditoria',color:'#315fb3'}],stages});assert.equal(w.plannerTest.order('c','a'),true);let data=JSON.parse(w.localStorage.getItem('ciclo-estudos-v1:cloud:order'));assert.deepEqual(data.stages.map(s=>s.id),['c','a','b']);assert.equal(data.stages[0].done,200);assert.equal(w.plannerTest.order('c','b',true),true);data=JSON.parse(w.localStorage.getItem('ciclo-estudos-v1:cloud:order'));assert.deepEqual(data.stages.map(s=>s.id),['a','b','c']);assert.equal(w.plannerTest.order('a','a'),false);w.close();});

test('task question counts can be blank and can be saved for page units',async()=>{const d=await boot({id:'counts'}),w=d.window;w.plannerTest.set({subjects:[{id:'a',name:'Auditoria',color:'#315fb3',contents:['Questões']}],stages:[{id:'s',subjectId:'a',content:'Questões',mode:'task',unit:'páginas',target:10,done:0}]});w.plannerTest.task('s');assert.equal(w.document.getElementById('taskQuestions').hidden,false);assert.equal(w.document.getElementById('taskCorrect').required,false);w.document.getElementById('taskUnits').value=2;w.document.getElementById('taskForm').dispatchEvent(new w.Event('submit',{cancelable:true}));let data=JSON.parse(w.localStorage.getItem('ciclo-estudos-v1:cloud:counts'));assert.equal(data.history.length,1);w.plannerTest.task('s');w.document.getElementById('taskUnits').value=1;w.document.getElementById('taskCorrect').value=7;w.document.getElementById('taskWrong').value=3;w.document.getElementById('taskTopic').value='Evidência';w.document.getElementById('taskForm').dispatchEvent(new w.Event('submit',{cancelable:true}));data=JSON.parse(w.localStorage.getItem('ciclo-estudos-v1:cloud:counts'));assert.equal(data.history[1].correct,7);assert.equal(data.history[1].wrong,3);assert.ok(data.subjects[0].topics.includes('Evidência'));w.close();});
test('subject topics accept multiple lines and are suggested in reviews with new badge',async()=>{const d=await boot({id:'topics'}),w=d.window;w.document.querySelector('[data-tab="subjects"]').click();w.document.getElementById('newSubject').click();w.document.getElementById('subjectName').value='Auditoria';w.document.getElementById('subjectTopics').value='Evidência\nDocumentação\nEvidência';w.document.getElementById('subjectForm').dispatchEvent(new w.Event('submit',{cancelable:true}));const data=JSON.parse(w.localStorage.getItem('ciclo-estudos-v1:cloud:topics'));assert.equal(data.subjects[0].topics.length,2);w.document.querySelector('[data-tab="reviews"]').click();w.document.getElementById('insertReview').click();assert.equal(w.document.getElementById('manualReviewContentList').children.length,2);const input=w.document.getElementById('manualReviewContent');input.value='Novo assunto';input.dispatchEvent(new w.Event('input',{bubbles:true}));assert.equal(w.document.getElementById('manualReviewContentNewTag').hidden,false);input.value='Evidência';input.dispatchEvent(new w.Event('input',{bubbles:true}));assert.equal(w.document.getElementById('manualReviewContentNewTag').hidden,true);w.close();});

test('cycle totals supports synthetic view and descending hours without reordering stages',async()=>{const d=await boot({id:'totals'}),w=d.window;w.plannerTest.set({subjects:[{id:'a',name:'Primeira',color:'#315fb3'},{id:'b',name:'Segunda',color:'#315fb3'}],stages:[{id:'a1',subjectId:'a',content:'Teoria',target:1800,done:0},{id:'b1',subjectId:'b',content:'Questões',target:7200,done:0}]});w.document.querySelector('[data-tab="cycle"]').click();assert.equal(w.document.getElementById('cycleTotalsView').value,'analytic');assert.equal(w.document.getElementById('cycleTotalsSort').value,'hours');assert.equal(w.document.querySelectorAll('.cycle-layout aside .total-activity').length,2);w.document.getElementById('cycleTotalsView').value='synthetic';w.document.getElementById('cycleTotalsView').dispatchEvent(new w.Event('change',{bubbles:true}));assert.equal(w.document.querySelectorAll('.cycle-layout aside .total-activity').length,0);w.document.querySelector('[data-expand-total]').click();assert.equal(w.document.querySelectorAll('.cycle-layout aside .total-activity').length,1);w.document.querySelector('[data-expand-total]').click();const mode=w.document.getElementById('cycleTotalsView');mode.value='synthetic';mode.dispatchEvent(new w.Event('change',{bubbles:true}));assert.equal(w.document.querySelectorAll('.cycle-layout aside .total-activity').length,0);const sort=w.document.getElementById('cycleTotalsSort');sort.value='hours';sort.dispatchEvent(new w.Event('change',{bubbles:true}));assert.equal(w.document.querySelector('[data-total-subject]').dataset.totalSubject,'b');const data=JSON.parse(w.localStorage.getItem('ciclo-estudos-v1:cloud:totals'));assert.deepEqual(data.stages.map(s=>s.id),['a1','b1']);w.close();});

test('record layout supports today other date and custom activity while keeping category fields',async()=>{const d=await boot({id:'record-ui'}),w=d.window;const st={id:'s',subjectId:'a',content:'Questões',mode:'time',target:3600,done:0};w.plannerTest.configure({subjects:[{id:'a',name:'Auditoria',color:'#315fb3',contents:['Questões','Videoaula']}],stages:[st],session:{stageId:'s',elapsed:600,running:false,last:Date.now(),mode:'elapsed',phase:'work',phaseLeft:1500}});w.plannerTest.record();assert.equal(w.document.getElementById('recordQuestionsBox').hidden,false);assert.equal(w.document.getElementById('recordVideosBox').hidden,true);const choice=w.document.getElementById('recordActivityChoice');choice.value='Videoaula';choice.dispatchEvent(new w.Event('change'));assert.equal(w.document.getElementById('recordVideosBox').hidden,false);assert.equal(w.document.getElementById('recordQuestionsBox').hidden,true);w.document.querySelector('[data-record-day="other"]').click();const day=w.document.getElementById('recordOtherDate');day.value='2026-10-01';day.dispatchEvent(new w.Event('change'));assert.equal(w.document.getElementById('recordDate').value.slice(0,10),'2026-10-01');choice.value='__other__';choice.dispatchEvent(new w.Event('change'));const name=w.document.getElementById('recordOtherActivity');assert.equal(name.required,true);name.value='Leitura de lei';name.dispatchEvent(new w.Event('input'));assert.equal(w.document.getElementById('recordContent').value,'Leitura de lei');assert.ok(w.document.getElementById('saveStudyRecord').closest('.record-save-footer'));w.close();});

test('stage menu opens popup showing only recent studies of that subject',async()=>{const d=await boot({id:'recent'}),w=d.window;w.plannerTest.configure({subjects:[{id:'a',name:'Auditoria',color:'#315fb3',contents:['Questões']},{id:'b',name:'Direito',color:'#315fb3',contents:[]}],stages:[{id:'s',subjectId:'a',content:'Questões',target:1800,done:0}],history:[{id:'h1',kind:'study',subjectId:'a',content:'Questões',topic:'Evidência',date:'2026-10-15T12:00:00Z',seconds:600},{id:'h2',kind:'study',subjectId:'b',content:'Teoria',topic:'Tópico de outra matéria',date:'2026-10-15T12:00:00Z',seconds:600}]});w.document.querySelector('[data-tab="cycle"]').click();assert.ok(w.document.querySelector('[data-manual-stage="s"]'));w.document.querySelector('[data-subject-last-studies="a"]').click();assert.equal(w.document.getElementById('subjectRecentDialog').open,true);assert.match(w.document.getElementById('subjectRecentContent').textContent,/Evidência/);assert.doesNotMatch(w.document.getElementById('subjectRecentContent').textContent,/Tópico de outra matéria/);w.close();});

test('quick clock waits for play, keeps elapsed on subject selection and confirms deletion',async()=>{const d=await boot({id:'clock'}),w=d.window,$=id=>w.document.getElementById(id);w.plannerTest.set({subjects:[{id:'a',name:'Auditoria',contents:['Conteúdo novo'],color:'#315fb3'}],stages:[]});$('quickClock').click();let data=()=>JSON.parse(w.localStorage.getItem('ciclo-estudos-v1:cloud:clock'));assert.equal(data().session.running,false);$('focusToggle').click();assert.equal(data().session.running,true);assert.ok($('quickSelection').classList.contains('select-subject-cue'));const session=data().session;session.elapsed=42;w.plannerTest.configure({session});$('quickSubject').value='a';$('quickSubject').dispatchEvent(new w.Event('change'));assert.ok(data().session.elapsed>=42&&data().session.elapsed<43);assert.equal(data().session.running,true);$('focusCancel').click();assert.equal($('closeTimerDialog').open,true);assert.ok(data().session);$('keepTimer').click();assert.ok(data().session);$('focusCancel').click();$('deleteTimer').click();assert.equal(data().session,null);assert.equal(data().history.length,0);assert.equal($('testTimerNotification'),null);w.close();});

test('edital imports 379 hierarchical topics without duplicating and parent checks descendants',async()=>{const d=await boot({id:'edital'}),w=d.window,$=id=>w.document.getElementById(id);w.document.querySelector('[data-tab="edital"]').click();$('editalSeedImport').click();let e=w.plannerTest.edital();assert.equal(e.subjects.length,14);assert.equal(e.subjects.reduce((n,m)=>n+m.topics.length,0),379);$('editalSeedImport').click();assert.equal(e.subjects.reduce((n,m)=>n+m.topics.length,0),379);const m=e.subjects[0],parent=m.topics[0];let input=w.document.querySelector(`[data-edital-check="${parent.id}"]`);input.checked=true;input.dispatchEvent(new w.Event('change',{bubbles:true}));assert.ok(m.topics.filter(t=>t.number.startsWith(parent.number+'.')).every(t=>t.done));assert.equal(m.topics.find(t=>t.number==='2').done,false);$('editalPlanOpen').click();assert.equal($('planningWizardDialog').open,true);w.close();});
test('edital plan validates proportions, scales hours to exam and preserves records when applied',async()=>{const d=await boot({id:'plan'}),w=d.window,$=id=>w.document.getElementById(id);w.document.querySelector('[data-tab="edital"]').click();$('editalSeedImport').click();const subjects=w.plannerTest.edital().subjects.slice(0,2);const exam=new Date();exam.setDate(exam.getDate()+14);const config={examDate:exam.getFullYear()+'-'+String(exam.getMonth()+1).padStart(2,'0')+'-'+String(exam.getDate()).padStart(2,'0'),dailyHours:3,blockMinutes:45,topicHours:2,weekdays:[0,1,2,3,4,5,6]};const p=w.plannerTest.buildPlan(config,subjects);assert.equal(p.availableDays,14);assert.equal(p.capacity,42);assert.ok(p.scheduledSeconds>21*3600);assert.ok(p.coverage.total>0);assert.ok(p.stages.every(s=>s.target>=1200&&s.target<=86400));assert.throws(()=>w.plannerTest.buildPlan(config,[{...subjects[0],ratios:[50,50,50]}]),/100%/);assert.throws(()=>w.plannerTest.buildPlan({...config,examDate:'2000-01-01'},subjects));const history=[{id:'old',kind:'study',subjectId:subjects[0].subjectId,name:'Estudo anterior',seconds:600,date:new Date().toISOString()}];w.plannerTest.configure({history});assert.equal(w.plannerTest.applyPlan(p,false),true);const saved=JSON.parse(w.localStorage.getItem('ciclo-estudos-v1:cloud:plan'));assert.equal(saved.history.length,1);assert.equal(saved.goals.daily,10800);assert.equal(saved.stages.length,p.stages.length);assert.equal(saved.edital.plan.applied,true);const after=new Date(exam);after.setDate(after.getDate()+2);assert.ok(Object.keys(w.plannerTest.project(after)).every(date=>date<config.examDate));w.close();});

test('multiple plannings preserve independent stages progress and settings through switching and backup',async()=>{const d=await boot({id:'multi'}),w=d.window;w.plannerTest.set({subjects:[{id:'a',name:'Direito',color:'#315fb3',contents:['Questões']}],stages:[{id:'legacy',subjectId:'a',content:'Questões',target:1800,done:600}]});w.document.querySelector('[data-tab="cycle"]').click();assert.equal(w.document.getElementById('pageTitle').textContent,'Planejamento');const legacy=w.plannerTest.plans()[0];assert.equal(legacy.data.stages[0].done,600);const created=w.plannerTest.newPlan('Segundo plano',[{subjectId:'a',content:'Questões',mode:'time',target:1500,done:0}],{dailyHours:2,weekdays:[0,1,2],minimumMinutes:25});assert.ok(created);assert.ok(w.document.getElementById('planningSelector'));w.plannerTest.assign({subjectId:'a',content:'Questões'});const entry={id:'new',kind:'study',name:'Direito',subjectId:'a',content:'Questões',stageId:created.data.stages[0].id,roundId:w.plannerTest.round(),seconds:300,countPlan:true,date:new Date().toISOString()};w.plannerTest.apply(entry);w.plannerTest.save();assert.equal(entry.planningId,created.id);assert.equal(w.plannerTest.switchPlan(legacy.id),true);assert.equal(w.plannerTest.plans().find(p=>p.id===created.id).data.stages[0].done,300);assert.equal(w.document.getElementById('doneStat').textContent.includes('10'),true);const edited={...entry,seconds:450};w.plannerTest.assign(edited,entry);w.plannerTest.apply(edited,entry);w.plannerTest.save();assert.equal(w.plannerTest.plans().find(p=>p.id===created.id).data.stages[0].done,450);assert.equal(w.plannerTest.plans().find(p=>p.id===legacy.id).data.stages[0].done,600);assert.equal(w.plannerTest.switchPlan(created.id),true);const saved=JSON.parse(w.localStorage.getItem('ciclo-estudos-v1:cloud:multi'));assert.equal(saved.goals.daily,7200);const restored=w.plannerTest.validate({format:'ciclo-estudos-backup',version:1,data:saved});assert.equal(restored.plannings.length,2);assert.equal(restored.activePlanningId,created.id);w.close();});
test('planning wizard creates a separate plan and enforces minimum blocks even with small budgets',async()=>{const d=await boot({id:'wizard'}),w=d.window,$=id=>w.document.getElementById(id);w.plannerTest.set({subjects:[{id:'a',name:'Direito',color:'#315fb3',contents:['Conteúdo novo']}],stages:[]});w.document.querySelector('[data-tab="cycle"]').click();$('newPlanning').click();w.document.querySelector('[data-pw-path="simple"]').click();$('pwName').value='Minha prova';$('pwNext').click();$('pwNext').click();const exam=new Date();exam.setDate(exam.getDate()+30);$('pwExam').value=exam.toISOString().slice(0,10);$('pwDaily').value='1';assert.equal($('pwMinimum'),null);assert.equal($('pwBlock'),null);assert.equal($('pwTopicHours'),null);$('pwNext').click();assert.match($('planningWizardMain').textContent,/Confira e ajuste/);$('pwNext').click();let saved=JSON.parse(w.localStorage.getItem('ciclo-estudos-v1:cloud:wizard'));assert.equal(saved.plannings[0].name,'Minha prova');assert.ok(saved.stages.every(s=>s.target>=1200));assert.equal($('planningWizardDialog').open,false);const many=Array.from({length:14},(_,i)=>({id:'e'+i,subjectId:'a',name:'Matéria '+i,topics:[],weight:1,level:'intermediate',ratios:[30,40,30]}));const p=w.plannerTest.buildPlan({examDate:exam.toISOString().slice(0,10),dailyHours:.5,weekdays:[0,1],blockMinutes:25,minimumMinutes:20,topicHours:2},many);assert.ok(p.cycleWeeks>1);assert.ok(p.stages.every(s=>s.target>=1200));w.close();});

