test('task goal settings use hours and weekdays to project daily and weekly tasks without requiring a clock',async()=>{const d=await boot({id:'task-availability-goals'}),w=d.window,p=w.plannerTest,$=id=>w.document.getElementById(id);p.set({subjects:[{id:'a',name:'Direito',color:'#315fb3',contents:[]}],stages:[]});w.document.querySelector('[data-tab="goals"]').click();$('goalModeTask').click();assert.ok($('taskAvailabilityHours'));assert.equal($('dailyTaskGoal').type,'hidden');assert.equal($('weeklyTaskGoal').type,'hidden');$('taskAvailabilityHours').value='2';$('taskAvailabilityHours').dispatchEvent(new w.Event('input',{bubbles:true}));for(const input of w.document.querySelectorAll('[data-goal-task-day]')){input.checked=Number(input.value)<5;input.dispatchEvent(new w.Event('change',{bubbles:true}));}assert.equal($('dailyTaskGoal').value,'4');assert.equal($('weeklyTaskGoal').value,'20');assert.match($('taskAvailabilityPreview').textContent,/10h/);$('goalAlerts').checked=false;$('goalsForm').dispatchEvent(new w.Event('submit',{bubbles:true,cancelable:true}));await new Promise(resolve=>setTimeout(resolve,20));const data=JSON.parse(w.localStorage.getItem('ciclo-estudos-v1:cloud:task-availability-goals'));assert.equal(data.measurementMode,'task');assert.equal(data.goals.dailyTasks,4);assert.equal(data.goals.weeklyTasks,20);assert.equal(data.goals.daily,0);assert.equal(data.goals.taskAvailability.dailyHours,2);assert.deepEqual(data.planner.weekdays,[0,1,2,3,4]);w.document.querySelector('[data-tab="goals"]').click();if(!$('taskAvailabilityHours'))$('goalModeTask').click();assert.equal($('taskAvailabilityHours').value,'2');for(const input of w.document.querySelectorAll('[data-goal-task-day]')){input.checked=false;input.dispatchEvent(new w.Event('change',{bubbles:true}));}$('goalsForm').dispatchEvent(new w.Event('submit',{bubbles:true,cancelable:true}));assert.equal($('taskAvailabilityError').hidden,false);assert.equal(JSON.parse(w.localStorage.getItem('ciclo-estudos-v1:cloud:task-availability-goals')).goals.weeklyTasks,20);w.close();});

test('task planning availability persists for replan and uses measured task duration when available',async()=>{const d=await boot({id:'task-availability-plan'}),w=d.window,p=w.plannerTest,$=id=>w.document.getElementById(id);p.set({subjects:[{id:'a',name:'Direito',color:'#315fb3',contents:['Revisão']}],stages:[]});p.configure({history:[{id:'pace',kind:'study',name:'Direito',subjectId:'a',content:'Revisão',studyMode:'task',unit:'tarefas',units:1,targetSnapshot:1,baselineUnits:0,seconds:3600,date:new Date().toISOString()}]});w.document.querySelector('[data-tab="cycle"]').click();$('newPlanning').click();w.document.querySelector('[data-pw-path="simple"]').click();w.document.querySelector('[data-pw-measurement="task"]').click();$('pwNext').click();$('pwNext').click();assert.equal($('pwTaskBasis'),null);$('pwTaskHours').value='2';$('pwTaskHours').dispatchEvent(new w.Event('input',{bubbles:true}));for(const input of w.document.querySelectorAll('[data-pw-day]')){input.checked=Number(input.value)<5;input.dispatchEvent(new w.Event('change',{bubbles:true}));}assert.equal($('pwDailyTasks').value,'2');assert.equal($('pwWeeklyTasks').value,'10');$('pwNext').click();$('pwNext').click();const data=JSON.parse(w.localStorage.getItem('ciclo-estudos-v1:cloud:task-availability-plan'));assert.equal(data.goals.dailyTasks,2);assert.equal(data.goals.weeklyTasks,10);assert.equal(data.goals.taskAvailability.dailyHours,2);assert.equal(data.edital.plan.availabilityWeeklyHours,10);assert.equal(data.edital.plan.estimatedTaskMinutes,60);$('replanPlanning').click();$('pwNext').click();$('pwNext').click();assert.equal($('pwTaskHours').value,'2');assert.equal(w.document.querySelectorAll('[data-pw-day]:checked').length,5);w.close();});

test('time goals calculate weekly hours from selected days and expose only the reminder check',async()=>{const d=await boot({id:'time-days'}),w=d.window,$=id=>w.document.getElementById(id);w.document.querySelector('[data-tab="goals"]').click();$('goalModeTime').click();assert.equal($('weeklyHours').readOnly,true);for(const id of ['alertStart','alertEnd','alertInterval','enableNotifications'])assert.equal($(id),null);assert.ok(!$('goalsForm').textContent.includes('Testar cobrança'));$('dailyHours').value='2';$('dailyHours').dispatchEvent(new w.Event('input'));for(const input of w.document.querySelectorAll('[data-goal-time-day]')){input.checked=[0,2,4].includes(Number(input.value));input.dispatchEvent(new w.Event('change'));}assert.equal($('weeklyHours').value,'6');$('goalAlerts').checked=false;$('goalsForm').dispatchEvent(new w.Event('submit',{cancelable:true}));await new Promise(r=>setTimeout(r,20));const saved=JSON.parse(w.localStorage.getItem('ciclo-estudos-v1:cloud:time-days'));assert.equal(saved.goals.daily,7200);assert.equal(saved.goals.weekly,21600);assert.deepEqual(saved.planner.weekdays,[0,2,4]);w.document.querySelector('[data-tab="goals"]').click();if(!$('dailyHours'))$('goalModeTime').click();assert.equal(w.document.querySelectorAll('[data-goal-time-day]:checked').length,3);for(const input of w.document.querySelectorAll('[data-goal-time-day]'))input.checked=false;$('goalsForm').dispatchEvent(new w.Event('submit',{cancelable:true}));assert.equal($('timeAvailabilityError').hidden,false);assert.equal(JSON.parse(w.localStorage.getItem('ciclo-estudos-v1:cloud:time-days')).goals.weekly,21600);w.close();});

test('goal reminders follow platform entry and study days instead of old clock windows',async()=>{const d=await boot({id:'access-reminders'}),w=d.window,p=w.plannerTest;const initial=w.Date.now(),day=(new w.Date(initial+11*60000).getDay()+6)%7;p.configure({goals:{daily:7200,weekly:36000,dailyTasks:0,weeklyTasks:0,alerts:true,start:'00:00',end:'00:01',interval:15,lastReminderAt:0},planner:{weekdays:[day]}});assert.equal(p.reminderDue(false),false);w.Date.now=()=>initial+11*60000;assert.equal(p.reminderDue(false),true);p.configure({planner:{weekdays:[(day+1)%7]}});assert.equal(p.reminderDue(false),false);p.configure({planner:{weekdays:[day]},session:{running:true}});assert.equal(p.reminderDue(false),false);p.configure({session:null,goals:{daily:7200,weekly:36000,alerts:true,lastReminderAt:initial}});assert.equal(p.reminderDue(false),false);w.close();});

test('new account setup offers a ready-made exam or manual subjects and unlocks goals after catalog selection',async()=>{const d=await boot({id:'setup-exam-choice'}),w=d.window,$=id=>w.document.getElementById(id);assert.match($('content').textContent,/Escolha sua prova ou cadastre suas matérias/);assert.match($('setupSubjects').textContent,/Cadastrar matérias manualmente/);assert.equal($('setupGoals').disabled,true);$('setupExam').click();assert.equal($('examChoiceDialog').open,true);const choice=w.document.querySelector('[data-exam-catalog]');assert.ok(choice);choice.click();assert.equal($('examChoiceDialog').open,false);w.document.querySelector('[data-tab="home"]').click();assert.equal($('setupGoals').disabled,false);const saved=JSON.parse(w.localStorage.getItem('ciclo-estudos-v1:cloud:setup-exam-choice'));assert.ok(saved.subjects.length>0);assert.ok(saved.edital.subjects.some(m=>m.topics.length));assert.equal(saved.stages.length,0);w.close();});

test('wizard can plan only syllabus subjects without altering topics and preserves choice on replan',async()=>{for(const mode of ['time','task']){const user='subject-scope-'+mode,d=await boot({id:user}),w=d.window,p=w.plannerTest,$=id=>w.document.getElementById(id);p.createExam(p.examCatalog()[0]);const before=JSON.parse(w.localStorage.getItem('ciclo-estudos-v1:cloud:'+user)).edital.subjects;w.document.querySelector('[data-tab="cycle"]').click();$('newPlanning').click();w.document.querySelector('[data-pw-path="detail"]').click();if(mode==='task')w.document.querySelector('[data-pw-measurement="task"]').click();$('pwNext').click();assert.equal(w.document.querySelector('[data-pw-content-scope="topics"]').getAttribute('aria-pressed'),'false');w.document.querySelector('[data-pw-content-scope="subjects"]').click();$('pwNext').click();$('pwNext').click();$('pwNext').click();$('pwNext').click();assert.equal(w.document.querySelector('[data-topic-mastery]'),null);assert.match($('planningWizardMain').textContent,/Somente matérias/);$('pwNext').click();const saved=JSON.parse(w.localStorage.getItem('ciclo-estudos-v1:cloud:'+user));assert.ok(saved.stages.length>0);assert.ok(saved.stages.every(s=>!s.curriculum?.topicId&&!s.topic));assert.equal(saved.edital.plan.contentScope,'subjects');assert.deepEqual(saved.edital.subjects,before);$('replanPlanning').click();$('pwNext').click();assert.equal(w.document.querySelector('[data-pw-content-scope="subjects"]').getAttribute('aria-pressed'),'true');w.close();}});

test('simple planning defaults to subjects while detail offers subjects first and topics second',async()=>{const d=await boot({id:'intuitive-simple'}),w=d.window,p=w.plannerTest,$=id=>w.document.getElementById(id);p.createExam(p.examCatalog()[0]);w.document.querySelector('[data-tab="cycle"]').click();$('newPlanning').click();assert.ok($('wizardChangeExam'));w.document.querySelector('[data-pw-path="simple"]').click();$('pwNext').click();assert.equal(w.document.querySelector('[data-pw-content-scope]'),null);$('pwNext').click();$('pwNext').click();assert.ok(w.document.querySelector('.planning-preview'));assert.equal(w.document.querySelector('[data-ratio-slider]'),null);$('pwNext').click();const saved=JSON.parse(w.localStorage.getItem('ciclo-estudos-v1:cloud:intuitive-simple'));assert.equal(saved.edital.plan.contentScope,'subjects');assert.ok(saved.stages.every(s=>!s.curriculum?.topicId));$('newPlanning').click();w.document.querySelector('[data-pw-path="detail"]').click();$('pwNext').click();assert.ok(w.document.querySelector('[data-pw-content-scope="subjects"].selected'));assert.deepEqual([...w.document.querySelectorAll('[data-pw-content-scope]')].map(b=>b.dataset.pwContentScope),['subjects','topics']);w.close();});

test('creation animation locks repeated clicks and creates just one plan after the delay',async()=>{const d=await boot({id:'animation'}),w=d.window,p=w.plannerTest,$=id=>w.document.getElementById(id);p.set({subjects:[{id:'a',name:'Direito',color:'#315fb3',contents:[]}],stages:[]});w.document.querySelector('[data-tab="cycle"]').click();$('newPlanning').click();w.document.querySelector('[data-pw-path="simple"]').click();$('pwNext').click();$('pwNext').click();$('pwNext').click();let finish,delay;w.setTimeout=(fn,ms)=>{if(ms===1500){finish=fn;delay=ms}return 0};$('pwNext').click();assert.equal(delay,1500);assert.equal($('planningWizardDialog').getAttribute('aria-busy'),'true');assert.equal($('pwNext').disabled,true);assert.ok($('planningCreationProgress'));$('pwNext').click();assert.equal(p.plans().length,0);const cancel=new w.Event('cancel',{cancelable:true});$('planningWizardDialog').dispatchEvent(cancel);assert.equal(cancel.defaultPrevented,true);finish();assert.equal(p.plans().length,1);assert.equal($('planningWizardDialog').open,false);assert.equal($('planningCreationProgress'),null);w.close();});

test('home focuses next study and plan menus duplicate without changing original progress',async()=>{const d=await boot({id:'intuitive-home'}),w=d.window,p=w.plannerTest,$=id=>w.document.getElementById(id);p.set({subjects:[{id:'a',name:'Direito',color:'#315fb3',contents:[]}],stages:[]});p.newPlan('Meu plano',[{subjectId:'a',content:'Conteúdo novo',target:3600,done:0}],{dailyHours:2,weekdays:[0,1,2,3,4,5,6],minimumMinutes:20});p.configure({ui:{setupStarted:false,setupGoalsComplete:true},stages:[{id:'s',subjectId:'a',content:'Conteúdo novo',target:3600,done:600}]});p.save();w.document.querySelector('[data-tab="home"]').click();assert.ok($('dailyFocus'));assert.ok($('homeBeginStudy'));assert.equal($('studyContext'),null);$('homeSeePlanning').click();assert.ok($('editPlanningProminent'));assert.ok($('renamePlanning').closest('details'));assert.ok($('deletePlanning').closest('details'));assert.equal($('planningSelector'),null);$('duplicatePlanning').click();const saved=JSON.parse(w.localStorage.getItem('ciclo-estudos-v1:cloud:intuitive-home'));assert.equal(saved.plannings.length,2);assert.equal(saved.plannings[0].data.stages[0].done,600);assert.equal(saved.stages[0].done,0);assert.ok($('planningSelector'));w.close();});

test('undo restores only calendar order and topic markings while keeping study progress',async()=>{const d=await boot({id:'undo-interface'}),w=d.window,p=w.plannerTest,$=id=>w.document.getElementById(id);p.set({subjects:[{id:'a',name:'Direito',color:'#315fb3',contents:[]}],stages:[{id:'one',subjectId:'a',content:'Teoria',target:3600,done:600},{id:'two',subjectId:'a',content:'Questões',target:1800,done:0}]});p.order('two','one');$('studyUndoButton').click();let saved=JSON.parse(w.localStorage.getItem('ciclo-estudos-v1:cloud:undo-interface'));assert.deepEqual(saved.stages.map(s=>s.id),['one','two']);assert.equal(saved.stages[0].done,600);p.configure({edital:{subjects:[{id:'m',subjectId:'a',name:'Direito',topics:[{id:'t',number:'1',name:'Tema',done:false}],level:'intermediate',ratios:[30,45,25],weight:1}],plan:{}}});w.document.querySelector('[data-tab="edital"]').click();const input=w.document.querySelector('[data-edital-check="t"]');input.checked=true;input.dispatchEvent(new w.Event('change',{bubbles:true}));await Promise.resolve();assert.equal(p.edital().subjects[0].topics[0].done,true);$('studyUndoButton').click();assert.equal(p.edital().subjects[0].topics[0].done,false);w.close();});

test('mobile menu opens independently of desktop preference and closes accessibly',async()=>{const d=await boot({id:'mobile-menu'}),w=d.window,$=id=>w.document.getElementById(id);w.matchMedia=()=>({matches:true});$('mobileMenuToggle').click();assert.equal(w.document.body.classList.contains('mobile-nav-open'),true);assert.equal($('mobileMenuToggle').getAttribute('aria-expanded'),'true');$('toggleSidebar').click();assert.equal(w.document.body.classList.contains('mobile-nav-open'),false);assert.equal($('mobileMenuToggle').getAttribute('aria-expanded'),'false');assert.match(html,/@media\(max-width:380px\)/);assert.match(html,/env\(safe-area-inset-bottom\)/);w.close();});

test('organization choices start expanded and planning actions retain a readable foreground',async()=>{const d=await boot({id:'expanded-organization'}),w=d.window,p=w.plannerTest,$=id=>w.document.getElementById(id);p.set({subjects:[{id:'a',name:'Direito',color:'#315fb3',contents:[]}],stages:[]});p.newPlan('Plano',[{subjectId:'a',content:'Teoria',target:1800,done:0}],{dailyHours:2,weekdays:[0,1,2,3,4]});const menu=w.document.querySelector('.planning-options');assert.match(menu.querySelector('summary').textContent,/Mais ações/);assert.notEqual(w.getComputedStyle(menu.querySelector('summary')).color,'rgb(255, 255, 255)');menu.open=true;assert.ok($('renamePlanning'));$('newPlanning').click();w.document.querySelector('[data-pw-path="simple"]').click();assert.equal(w.document.querySelector('.optional-planning').open,true);assert.ok(w.document.querySelector('[data-pw-format="cycle"]'));assert.ok(w.document.querySelector('[data-pw-format="week"]'));w.close();});

test('flexible durations exceed the minimum with many subjects and retain total budgets in both scopes',async()=>{const d=await boot({id:'flexible-durations'}),w=d.window,p=w.plannerTest;const subjects=Array.from({length:12},(_,i)=>({id:'m'+i,subjectId:'a'+i,name:'Matéria '+i,weight:i%3+1,level:['beginner','intermediate','advanced'][i%3],ratios:[50,30,20],topics:[{id:'t'+i,number:'1',name:'Tema '+i,done:false}]}));p.set({subjects:subjects.map(m=>({id:m.subjectId,name:m.name,color:'#315fb3',contents:[]})),stages:[]});for(const scope of ['subjects','topics']){const input={...topicConfig(),dailyHours:2,weekdays:[0,1,2,3,4],examDate:'',contentScope:scope},auto=p.autoTimes(input,subjects),plan=p.buildPlan({...input,...auto},subjects),times=plan.stages.map(s=>s.target);assert.equal(auto.minimumMinutes,20);assert.ok(times.every(s=>s>=1200));assert.ok(times.some(s=>s>=1800));assert.ok(new Set(times).size>1);assert.ok(subjects.every(m=>plan.stages.some(s=>s.subjectId===m.subjectId)));assert.equal(plan.config.dailyHours,2);assert.equal(plan.weeklySeconds,36000);if(scope==='subjects')assert.equal(plan.scheduledSeconds,plan.subjects.reduce((n,m)=>n+m.budgets.reduce((a,b)=>a+b,0),0));}w.close();});

test('30 minute preferred stages are not rounded down to the 20 minute floor',async()=>{const d=await boot({id:'thirty-minutes'}),p=d.window.plannerTest;p.set({subjects:[{id:'a',name:'Direito',color:'#315fb3',contents:[]}],stages:[]});const m={id:'m',subjectId:'a',name:'Direito',level:'intermediate',weight:1,ratios:[100,0,0],topics:[]},plan=p.buildPlan({...topicConfig(),dailyHours:1,weekdays:[0],examDate:'',blockMinutes:30,minimumMinutes:20,contentScope:'subjects'},[m]);assert.equal(plan.stages.length,2);assert.ok(plan.stages.every(s=>s.target===1800));assert.equal(plan.stages.reduce((n,s)=>n+s.target,0),3600);d.window.close();});

test('creating from syllabus always offers simple or detailed before choosing a format',async()=>{const d=await boot({id:'choose-path-first'}),w=d.window,p=w.plannerTest,$=id=>w.document.getElementById(id);p.createExam(p.examCatalog()[0]);$('editalPlanOpen').click();assert.equal($('planningWizardDialog').open,true);assert.ok(w.document.querySelector('[data-pw-path="simple"]'));assert.ok(w.document.querySelector('[data-pw-path="detail"]'));assert.equal(w.document.querySelector('[data-pw-format]'),null);assert.equal($('pwManual'),null);w.document.querySelector('[data-pw-path="detail"]').click();assert.ok(w.document.querySelector('[data-pw-format="cycle"]'));$('planningWizardDialog').close();w.document.querySelector('[data-tab="cycle"]').click();$('newPlanning').click();assert.ok(w.document.querySelector('[data-pw-path="simple"]'));assert.ok(w.document.querySelector('[data-pw-path="detail"]'));assert.equal(w.document.querySelector('[data-pw-format]'),null);w.close();});

test('elapsed minimized timer shows remaining stage goal including previous progress and current session',async()=>{const d=await boot({id:'dock-remaining'}),w=d.window,p=w.plannerTest,$=id=>w.document.getElementById(id);p.set({subjects:[{id:'a',name:'Direito',color:'#315fb3',contents:['Anki']}],stages:[{id:'s',subjectId:'a',content:'Anki',target:900,done:300}]});p.configure({session:{stageId:'s',elapsed:120,running:false,last:Date.now(),mode:'elapsed',phase:'work',phaseLeft:1500}});w.document.querySelector('[data-tab="cycle"]').click();assert.match($('dockStatus').textContent,/Meta: 15min.*Faltam: 8min/);assert.equal($('dock').classList.contains('has-time-goal'),true);$('dockToggle').click();assert.match($('dockStatus').textContent,/Em andamento.*Faltam: 8min/);$('dockToggle').click();p.configure({session:{stageId:'s',elapsed:600,running:false,last:Date.now(),mode:'elapsed',phase:'work',phaseLeft:1500}});w.document.querySelector('[data-tab="cycle"]').click();assert.match($('dockStatus').textContent,/Meta cumprida/);assert.ok(!$('dockStatus').textContent.includes('-'));p.configure({session:{stageId:'s',elapsed:120,running:false,last:Date.now(),mode:'pomodoro',phase:'work',phaseLeft:1500}});w.document.querySelector('[data-tab="cycle"]').click();assert.equal($('dock').classList.contains('has-time-goal'),false);w.close();});

test('legacy report weekly-plan section stays removed from home and planning',async()=>{const d=await boot({id:'performance-panels'}),w=d.window,p=w.plannerTest;p.createExam(p.examCatalog()[0]);const examId=p.exams().find(e=>e.sourceId!=='legacy').id,plans=[{id:'week',examId,week:'2026-10-19',bank:'FGV',items:[{id:'t',discipline:'Direito',topic:'Tema',done:2,disciplinePriority:true}]}];p.performance(false,plans);w.document.querySelector('[data-tab="home"]').click();assert.equal(w.document.querySelector('.performance-weekly-panel'),null);p.performance(true,plans);w.document.querySelector('[data-tab="home"]').click();assert.equal(w.document.querySelector('.performance-weekly-panel'),null);w.document.querySelector('[data-tab="cycle"]').click();assert.equal(w.document.querySelector('.performance-weekly-panel'),null);p.performance(true,[{...plans[0],examId:'other'}]);w.document.querySelector('[data-tab="cycle"]').click();assert.equal(w.document.querySelector('.performance-weekly-panel'),null);w.close();});

test('performance priorities are opt in and full weekly plan adds only pending topics while preserving backup',async()=>{const d=await boot({id:'performance-optin'}),w=d.window,p=w.plannerTest;p.set({subjects:[{id:'a',name:'Direito',color:'#315fb3',contents:[]}],stages:[]});const examId=p.exams()[0].id,items=[{id:'priority',discipline:'Direito',topic:'Crédito tributário',done:2,disciplinePriority:true},{id:'other',discipline:'Contabilidade',topic:'Balanço',done:0,disciplinePriority:false},{id:'complete',discipline:'Direito',topic:'Concluído',done:10,disciplinePriority:true}];p.performance(true,[{id:'weekly',examId,week:'2026-10-19',bank:'FGV',items}]);const subject={id:'m',subjectId:'a',name:'Direito',topics:[],level:'intermediate',weight:1,ratios:[30,45,25]},base={...topicConfig(),examDate:'',dailyHours:2};const none=p.buildPlan(base,[subject]);assert.ok(none.stages.every(s=>!s.performanceSource));const priority=p.buildPlan({...base,performanceWeekly:{mode:'priority',planId:'weekly'}},[subject]);assert.equal(priority.stages.filter(s=>s.performanceSource).length,1);assert.equal(priority.config.performanceWeekly.questions,8);const all=p.buildPlan({...base,performanceWeekly:{mode:'all',planId:'weekly'}},[subject]);assert.equal(all.stages.filter(s=>s.performanceSource).length,2);assert.equal(all.config.performanceWeekly.questions,18);assert.equal(all.config.performanceWeekly.subjects[0].name,'Contabilidade');assert.ok(p.newPlan('Integrado',all.stages,all.config));const stored=JSON.parse(w.localStorage.getItem('ciclo-estudos-v1:cloud:performance-optin'));assert.ok(stored.subjects.some(s=>s.name==='Contabilidade'));assert.ok(p.validate({format:'ciclo-estudos-backup',version:1,data:stored}).stages.some(s=>s.performanceSource));w.close();});

test('returning from study registration resumes the same timer without creating a record',async()=>{const d=await boot({id:'resume-record'}),w=d.window,p=w.plannerTest,$=id=>w.document.getElementById(id);p.set({subjects:[{id:'a',name:'Direito',color:'#315fb3',contents:['Anki']}],stages:[{id:'s',subjectId:'a',content:'Anki',target:1800,done:0}]});p.configure({history:[],session:{stageId:'s',elapsed:485,running:false,last:Date.now(),mode:'pomodoro',phase:'work',phaseLeft:123}});p.record();assert.equal($('recordDialog').open,true);assert.match($('recordReturn').textContent,/Voltar aos estudos/);$('recordReturn').click();assert.equal($('recordDialog').open,false);assert.equal($('focusDialog').open,true);const saved=JSON.parse(w.localStorage.getItem('ciclo-estudos-v1:cloud:resume-record'));assert.equal(saved.session.elapsed,485);assert.equal(saved.session.running,true);assert.equal(saved.session.mode,'elapsed');assert.equal(saved.session.phaseLeft,123);assert.equal(saved.history.length,0);assert.equal(saved.stages[0].done,0);w.close()});

