test('report bridge reads only the signed-in account after permission and clears revoked results',async()=>{const d=await boot({id:'bridge-permission'}),w=d.window,p=w.plannerTest;p.set({subjects:[{id:'a',name:'Direito',color:'#315fb3',contents:[]}],stages:[]});const calls=[];let allowed=false;const client={from:table=>{calls.push({table,filters:[]});const call=calls.at(-1),q={select:()=>q,eq:(key,value)=>{call.filters.push([key,value]);return q},maybeSingle:async()=>({data:table==='performance_access'?(allowed?{user_id:'bridge-permission',role:'member'}:null):{payload:{insights:{mainBank:'FGV'},histories:[{bank:'FGV',end:'2026-10-19',mode:'snapshot',rows:[{discipline:'Direito',topic:'Revisão',total:10,correct:4}]}]}}})};return q}};assert.equal(await p.bridgeLoad(client),false);assert.equal(calls.some(c=>c.table==='performance_report_state'),false);allowed=true;assert.equal(await p.bridgeLoad(client),true);w.document.querySelector('[data-tab="cycle"]').click();assert.match(w.document.querySelector('.priority-summary-card').textContent,/1 assunto/);assert.ok(calls.every(c=>c.filters.some(([key,value])=>key==='user_id'&&value==='bridge-permission')));allowed=false;assert.equal(await p.bridgeLoad(client),false);assert.equal(w.document.querySelector('.report-priority-panel'),null);w.close()});

