test('cycle stage subject selector can register a new matter without losing the stage draft',async()=>{const d=await boot({id:'stage-new-matter'}),w=d.window,p=w.plannerTest,$=id=>w.document.getElementById(id);p.set({subjects:[{id:'a',name:'Direito',color:'#315fb3',contents:['Revisão']}],stages:[{id:'sa',subjectId:'a',content:'Revisão',target:3600,done:0}]});w.document.querySelector('[data-tab="cycle"]').click();$('editStagesHeader').click();const sel=$('stageEditor').querySelector('[data-subject]');assert.match(sel.lastElementChild.textContent,/Cadastrar nova matéria/);sel.value='__new_subject__';sel.dispatchEvent(new w.Event('change',{bubbles:true}));assert.equal($('subjectDialog').open,true);$('subjectName').value='Contabilidade';$('subjectForm').dispatchEvent(new w.Event('submit',{cancelable:true}));assert.equal($('subjectDialog').open,false);assert.equal($('cycleDialog').open,true);const after=$('stageEditor').querySelector('[data-subject]');assert.equal(after.selectedOptions[0].textContent,'Contabilidade');w.close();});
test('time and task topic plans rotate subjects and defer new-topic batches until prior practice',async()=>{const d=await boot({id:'interleaved-plan'}),w=d.window,p=w.plannerTest;const matters=['a','b'].map((id,index)=>({id:'m'+id,subjectId:id,name:'Matéria '+id,level:'intermediate',weight:1,ratios:[40,30,30],topics:Array.from({length:5},(_,i)=>({id:id+i,number:String(i+1),name:'Tópico '+i,done:false}))}));p.set({subjects:matters.map(m=>({id:m.subjectId,name:m.name,color:'#315fb3',contents:[]})),stages:[]});for(const mode of ['time','task']){const config={...topicConfig(),mode,dailyTasks:6,weeklyTasks:42,dailyHours:3,examDate:'',blockMinutes:25,taskActivities:[{unit:'tarefas',quantity:1},{unit:'questões',quantity:10},{unit:'tarefas',quantity:1}]},plan=p.buildPlan(config,matters),first=plan.stages.filter(s=>s.curriculum.phase==='theory');assert.ok(first.some(s=>s.curriculum.after&&plan.stages.find(p=>p.curriculum.key===s.curriculum.after)?.curriculum.phase==='questions'));const schedule=p.schedule(plan.stages,plan.config,{fresh:true}),flat=Object.entries(schedule.output).flatMap(([date,blocks])=>blocks.map(b=>({date,...b})));assert.equal(schedule.remaining,0);assert.ok(flat.some((b,i)=>i&&b.stageId!==flat[i-1].stageId));const firstPractice=flat.findIndex(b=>plan.stages.find(s=>s.curriculum.key===b.stageId)?.curriculum.phase==='questions'),lastTheory=flat.findLastIndex(b=>plan.stages.find(s=>s.curriculum.key===b.stageId)?.curriculum.phase==='theory');assert.ok(firstPractice>=0&&firstPractice<lastTheory);}w.close();});

test('subject-only task and time plans mix the saved activity list instead of batching each matter',async()=>{const d=await boot({id:'mix-general-activities'}),p=d.window.plannerTest;const subjects=['a','b','c'].map(id=>({id:'m'+id,subjectId:id,name:'Matéria '+id,topics:[],level:'intermediate',weight:1,ratios:[40,30,30]}));p.set({subjects:subjects.map(m=>({id:m.subjectId,name:m.name,color:'#315fb3',contents:[]})),stages:[]});for(const mode of ['task','time']){const plan=p.buildPlan({...topicConfig(),contentScope:'subjects',mode,examDate:'',weeklyTasks:18,dailyTasks:3,taskActivities:[{unit:'tarefas',quantity:1},{unit:'questões',quantity:10},{unit:'tarefas',quantity:1}]},subjects);assert.equal(new Set(plan.stages.slice(0,3).map(s=>s.subjectId)).size,3);const firstReview=plan.stages.findIndex(s=>s.content==='Revisão');assert.ok(firstReview>=3,'Reviews follow several study blocks');for(const id of ['a','b','c']){const theory=plan.stages.findIndex(s=>s.subjectId===id&&s.content==='Conteúdo novo'),questions=plan.stages.findIndex(s=>s.subjectId===id&&s.content==='Questões'),review=plan.stages.findIndex(s=>s.subjectId===id&&s.content==='Revisão');assert.ok(theory>=0&&questions>theory&&review>theory);assert.ok(review-theory>=2);}for(let i=1;i<plan.stages.length;i++){if(plan.stages[i].subjectId===plan.stages[i-1].subjectId)assert.ok(!plan.stages.slice(i+1).some(s=>s.subjectId!==plan.stages[i].subjectId));}}d.window.close();});
