async function tecCommand(w,type,extra={}){const requestId=w.crypto.randomUUID();return new Promise(resolve=>{const original=w.postMessage;w.postMessage=(m)=>{if(m.direction==='response'&&m.requestId===requestId){w.postMessage=original;resolve(m);}};w.dispatchEvent(new w.MessageEvent('message',{source:w,origin:w.location.origin,data:{channel:'ciclo-tec-v1',direction:'request',requestId,type,...extra}}));});}
