async function openTecMatchingBatch(user,subjects,stages,events){
 const d=await boot({id:user}),w=d.window,p=w.plannerTest;let now=w.Date.now();w.Date.now=()=>now;p.configure({subjects,stages,history:[]});p.save();w.document.getElementById('tecEnable').click();const context=(await tecCommand(w,'snapshot')).data.context,start=await tecCommand(w,'start',{context});assert.equal(start.ok,true);const sessionId=start.data.timer.sessionId;now+=120000;const finish=await tecCommand(w,'finish',{context,sessionId,payload:{events}});assert.equal(finish.ok,true);return {d,w,p,context,sessionId,save:()=>w.document.getElementById('tecBatchForm').dispatchEvent(new w.Event('submit',{cancelable:true})),saved:()=>JSON.parse(w.localStorage.getItem('ciclo-estudos-v1:cloud:'+user))};
}
test('TEC credits the pending question task by subject even when its planned topic differs',async()=>{
 const {w,save,saved,context,sessionId}=await openTecMatchingBatch('tec-subject-fallback',[{id:'a',name:'Auditoria',color:'#315fb3',contents:['Questões']},{id:'b',name:'Contabilidade',color:'#477eb2',contents:['Questões']}],[{id:'theory',subjectId:'a',content:'Teoria',target:1800,done:0},{id:'questions',subjectId:'a',content:'Questões',mode:'task',unit:'questões',target:10,done:3,topic:'Planejamento'},{id:'other',subjectId:'b',content:'Questões',mode:'task',unit:'questões',target:10,done:0}],[{id:'q1',subject:'Auditoria',topic:'Evidência',correct:4,wrong:3,elapsed:100}]);assert.equal(w.document.querySelector('[data-tec-field="stage"]').value,'questions');assert.match(w.document.querySelector('[data-tec-match-note]').textContent,/Matéria correspondente/);save();let data=saved();assert.equal(data.stages.find(st=>st.id==='questions').done,10);assert.equal(data.stages.find(st=>st.id==='theory').done,0);assert.equal(data.stages.find(st=>st.id==='other').done,0);assert.equal(data.history.length,1);assert.equal(data.history[0].stageId,'questions');assert.equal(data.history[0].units,7);assert.equal(data.history[0].seconds,120);assert.equal(data.history[0].countPlan,true);assert.equal(data.history[0].topic,'Evidência');const result=await tecCommand(w,'finish',{context,sessionId,payload:{events:[]}});assert.equal(result.data.status,'saved');assert.equal(saved().history.length,1);w.close();
});
test('TEC automatically advances grouped topics to the next pending question stage instead of reusing completed stages',async()=>{
 const {w,save,saved}=await openTecMatchingBatch('tec-stage-order',[{id:'a',name:'Direito',color:'#315fb3',contents:['Questões']}],[{id:'completed',subjectId:'a',content:'Questões',mode:'task',unit:'questões',target:2,done:2,topic:'Impostos'},{id:'first',subjectId:'a',content:'Questões',mode:'task',unit:'questões',target:2,done:0},{id:'second',subjectId:'a',content:'Questões',mode:'task',unit:'questões',target:2,done:0}],[{id:'q1',subject:'Direito',topic:'Impostos',correct:1,wrong:1,elapsed:60},{id:'q2',subject:'Direito',topic:'Taxas',correct:2,wrong:0,elapsed:120}]);assert.ok([...w.document.querySelectorAll('[data-tec-field="stage"]')].every(el=>el.value==='first'));save();const data=saved();assert.deepEqual(data.stages.map(st=>st.done),[2,2,2]);assert.deepEqual(data.history.map(h=>h.stageId),['first','second']);assert.equal(data.history.reduce((n,h)=>n+h.seconds,0),120);assert.equal(data.history.reduce((n,h)=>n+h.correct+h.wrong,0),4);w.close();
});
