test('TEC preserves explicit history-only selection and reselects a stage after changing the mapped subject',async()=>{
 const {w,save,saved}=await openTecMatchingBatch('tec-manual-stage-choice',[{id:'a',name:'Auditoria',color:'#315fb3',contents:['Questões']},{id:'b',name:'Direito',color:'#477eb2',contents:['Questões']}],[{id:'audit',subjectId:'a',content:'Questões',mode:'task',unit:'questões',target:10,done:0},{id:'law',subjectId:'b',content:'Questões',mode:'task',unit:'questões',target:10,done:0}],[{id:'q1',subject:'Auditoria',topic:'Evidência',correct:1,wrong:0,elapsed:60},{id:'q2',subject:'Auditoria',topic:'Planejamento',correct:1,wrong:0,elapsed:120}]);const rows=w.document.querySelectorAll('.tec-batch-row'),stage=rows[0].querySelector('[data-tec-field="stage"]');stage.value='';stage.dispatchEvent(new w.Event('change',{bubbles:true}));const matter=rows[1].querySelector('[data-tec-field="subject"]');matter.value='b';matter.dispatchEvent(new w.Event('change',{bubbles:true}));assert.equal(rows[1].querySelector('[data-tec-field="stage"]').value,'law');save();const data=saved();assert.equal(data.history[0].countPlan,false);assert.equal(data.history[1].stageId,'law');assert.equal(data.stages.find(st=>st.id==='audit').done,0);assert.equal(data.stages.find(st=>st.id==='law').done,1);w.close();
});

